document.querySelector('#rawObservation').onchange=e=>{rawObservation=e.target.checked;if(window.geoWeather.current)window.geoWeather.renderCurrent();};
document.querySelectorAll('[data-cloud-mode]').forEach(button=>button.onclick=()=>{cloudSim.enabled=button.dataset.cloudMode==='3d';if(cloudSim.enabled)playback.stop();document.querySelectorAll('[data-cloud-mode]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelector('#cloudControls').hidden=!cloudSim.enabled;document.querySelector('#imageControls').hidden=cloudSim.enabled;if(!cloudSim.enabled){if(!weatherStarted){weatherStarted=true;window.geoWeather.init();}else if(window.geoWeather.current)window.geoWeather.renderCurrent();}else document.querySelector('#surfaceLabel').textContent='観測風による移動 · 雲の形は模型';});
let previous=0;function render(t){requestAnimationFrame(render);if(!ready||document.hidden)return;const dt=Math.min((t-previous)/1000,.05);previous=t;if(rotating&&pointers.size===0)yaw-=dt*.065*speed;const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.75);const w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;gl.viewport(0,0,w,h);}gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);gl.uniform2f(uniforms.resolution,w,h);gl.uniform2f(uniforms.watermark,watermark[0],watermark[1]);for(const [k,val] of Object.entries({yaw,pitch,zoom,mode,panels:panels?1:0,rawObservation:rawObservation?1:0,fade:fade.value(t),weatherActive:weatherReady&&weatherEnabled&&!cloudSim.enabled?1:0}))gl.uniform1f(uniforms[k],val);gl.drawArrays(gl.TRIANGLES,0,6);cloudSim.tick(dt);cloudRenderer.draw({width:w,height:h,yaw,pitch,zoom,mode});}requestAnimationFrame(render);
